def check_border(g,out,bg):
    pts=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x!=bg]
    r0=min(r for r,c in pts);r1=max(r for r,c in pts);c0=min(c for r,c in pts);c1=max(c for r,c in pts)
    for r in range(len(g)):
        for c in range(len(g[0])):
            expected=g[r][c]
            if g[r][c]==bg and ((r in (r0,r1) and c0<=c<=c1) or (c in (c0,c1) and r0<=r<=r1)):
                expected=2
            if out[r][c]!=expected:return False,(r,c,out[r][c],expected)
    return True,None
